const contact = $('Loop Over Items').item.json;
const oppsResponse = $('Get State Opportunities').item.json;
const facetsResponse = $('Get State Facets').item.json;

const total = oppsResponse.total || 0;

// Parse facets
const setAsides = (facetsResponse.set_asides || [])
  .sort((a, b) => b.count - a.count)
  .slice(0, 5)
  .map(f => `${f.label}: ${f.count}`)
  .join(', ');

