- Set-aside breakdown: ${$json.enrichment.set_asides}
- Opportunity types: ${$json.enrichment.types}

ABOUT GOVTROVE:
- Free search tool for SAM.gov contract opportunities
- Filters by state, set-aside, NAICS, agency, keyword
- Daily email alerts for new matches
- One-pager PDF: https://govtrove.com/govtrove-one-pager.pdf
- Tracking link for this contact: ${$json.utm_link}

INSTRUCTIONS:
- Be genuine and conversational, not salesy
- Lead with a specific data point about their state
- Mention the one-pager PDF as an attachment reference
- Include the tracking link naturally
- Close with a low-pressure ask (e.g., "happy to jump on a quick call" or "would love your feedback")
- Sign as "Andrew"

FORMAT YOUR RESPONSE EXACTLY AS:
SUBJECT: [subject line here]
BODY:
[email body here]`
  }]
}) }}

parameters.jsCode:
const contact = $('Build Research Context').item.json.contact;
const enrichment = $('Build Research Context').item.json.enrichment;
const utmLink = $('Build Research Context').item.json.utm_link;
const response = $json;

let text = '';
try {
  text = response.content[0].text;
} catch (e) {
  return [{ json: { error: 'Failed to parse Claude response', raw: response } }];
}

// Parse SUBJECT: and BODY: from response
const subjectMatch = text.match(/SUBJECT:\s*(.+?)\n/);
const bodyMatch = text.match(/BODY:\s*\n([\s\S]+)$/);

const subject = subjectMatch ? subjectMatch[1].trim() : 'No subject parsed';
const body = bodyMatch ? bodyMatch[1].trim() : text;

return [{
  json: {
    contact_id: contact.id,
    office_name: contact.office_name,
    contact_name: contact.contact_name,
    contact_email: contact.email,
    state: contact.state,
    subject,
    body,
    utm_link: utmLink,
    enrichment,
    status: 'pending_review',
    generated_at: new Date().toISOString()
  }
}];

const fs = require('fs');

const drafts = $input.all().map(item => item.json);

const output = {
  generated_at: new Date().toISOString(),
  total_drafts: drafts.length,
  drafts
};

const filePath = '/home/node/output/apex-drafts.json';
fs.writeFileSync(filePath, JSON.stringify(output, null, 2));

return [{
  json: {
    message: `Saved ${drafts.length} drafts to ${filePath}`,
    total_drafts: drafts.length,
    file_path: filePath
  }
}];
